t-size: 16px;\n}\n.filter__list-item a:hover {\n  color: red;\n}\n.filter__list-item a span {\n  color: #545454;\n}\n\n.sort {\n  display: flex;\n  align-items: center;\n  gap: 15px;\n  margin-top: 15px;\n  margin-bottom: 15px;\n  flex-wrap: wrap;\n}\n\n.sort__ads {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.sort__ads span {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 500;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n}\n\n.sort__type-list {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.sort__type-list li {\n  cursor: pointer;\n}\n\n.sorted__output {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.sorted__output a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.sorted__output p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.sorted__output-list {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.sorted__output-list li {\n  opacity: 0.5;\n  border: 1px solid black;\n  padding: 5px;\n  color: black;\n  cursor: pointer;\n}\n\n.sorted__by {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.sorted__by p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.sorted__by-list {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.sorted__by-list-item {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.sorted__by-list-item a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n  cursor: pointer;\n}\n.sorted__by-list-item a:hover {\n  color: red;\n}\n\n.sorted__by-list-item-img {\n  max-width: 15px;\n  max-height: 15px;\n}\n.sorted__by-list-item-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n@media (max-width: 992px) {\n  .sort {\n    justify-content: center;\n  }\n}\n.advertisement__list {\n  flex: 1 1 680px;\n}\n\n.default__item .advertisement__list-item {\n  display: flex;\n  gap: 40px;\n  padding: 5px;\n  border-bottom: 1px solid #D4D4D4;\n}\n.default__item ~ .vip__wrap {\n  flex: 1 0 250px;\n}\n.default__item .advertisement__list-item-img {\n  display: block;\n  max-width: 180px;\n  max-height: 140px;\n  flex: 0 1 140px;\n}\n.default__item .advertisement__list-item-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.default__item .advertisement__list-item-about {\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  position: relative;\n}\n.default__item .advertisement__list-item-about-favorites {\n  cursor: pointer;\n  display: block;\n  width: 18px;\n  height: 18px;\n  background: url(../img/favorite.png) no-repeat center/cover;\n  position: absolute;\n  bottom: 0;\n  right: 0;\n}\n.default__item .advertisement__list-item:has(.advertisement__list-item-action) .advertisement__list-item-about-favorites {\n  bottom: 25px;\n}\n.default__item .advertisement__list-item-title {\n  align-self: flex-start;\n}\n.default__item .advertisement__list-item-title a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 18px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n.default__item .advertisement__list-item-title a:hover {\n  color: red;\n}\n.default__item .advertisement__list-item-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n}\n.default__item .advertisement__list-item-about-text-list li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color